var ITEMS=[["Alanine","A simple nonessential amino acid; made by the body."], ["Arginine","Conditionally essential; blood flow and wound healing."], ["Asparagine","Nonessential; nervous system function."], ["Aspartic acid","Nonessential; energy metabolism."], ["Cysteine","Forms disulfide bonds that shape proteins."], ["Glutamic acid","Nonessential; also a neurotransmitter as glutamate."], ["Glutamine","Fuel for gut and immune cells."], ["Glycine","The smallest amino acid; collagen backbone."], ["Histidine","Essential; histamine and growth."], ["Isoleucine","Essential branched-chain; muscle energy."], ["Leucine","Essential branched-chain; triggers muscle building."], ["Lysine","Essential; collagen and calcium absorption."], ["Methionine","Essential sulfur donor; starts every protein chain."], ["Phenylalanine","Essential; becomes tyrosine and neurotransmitters."], ["Proline","Kinks protein chains; key in collagen."], ["Serine","Nonessential; cell signaling."], ["Threonine","Essential; gut lining and collagen."], ["Tryptophan","Essential; becomes serotonin and melatonin."], ["Tyrosine","Becomes dopamine and thyroid hormones."], ["Valine","Essential branched-chain; muscle coordination."], ["What is protein","Proteins are folded chains of amino acids \u2014 the machines of the cell: enzymes, muscles, antibodies."], ["Essential vs nonessential","Nine amino acids must come from food; the body makes the other eleven."], ["Complete proteins","Foods with all nine essentials: meat, eggs, dairy, soy, quinoa."], ["Protein synthesis","Ribosomes read mRNA and link amino acids into chains that fold into working proteins."], ["Denaturation","Heat or acid unfolds proteins \u2014 frying an egg denatures its albumin irreversibly."]];
